+	if err := json.Unmarshal(stdout, &resp); err != nil {
+		return nil, fmt.Errorf("compact-transcript: invalid JSON: %w", err)
+	}
+
+	compacted, err := resp.toCompactedTranscript()
+	if err != nil {
+		return nil, err
+	}
+	return compacted, nil
