func buildCompactTranscript(ctx context.Context, ag agent.Agent, redacted redact.RedactedBytes, state *SessionState, writeOpts *cpkg.WriteCommittedOptions) time.Duration {
	compactStart := time.Now()
	compactCtx, compactSpan := perf.Start(ctx, "compact_transcript_v2")
	defer compactSpan.End()
	if settings.IsCheckpointsV2Enabled(ctx) {
		if compactor, ok := agent.AsTranscriptCompactor(ag); ok {
			if compacted := compactTranscriptForExternalAgent(compactCtx, compactor, state.SessionID, state.TranscriptPath); compacted != nil {
				writeOpts.CompactTranscript = compacted.Transcript
				writeOpts.CompactTranscriptStart = state.CompactTranscriptStart
			}
			return time.Since(compactStart)
		} else if _, ok := ag.(agent.CapabilityDeclarer); ok {
			logging.Warn(compactCtx, "external transcript compaction unavailable, skipping transcript.jsonl on /main",
				slog.String("session_id", state.SessionID),
				slog.String("agent", string(ag.Name())),
			)
			return time.Since(compactStart)
		}

		// Generate scoped compact (only new content) for line counting and offset calculation.
		scopedCompact := compactTranscriptForV2(compactCtx, ag, redacted, state.CheckpointTranscriptStart)
		// Generate full compact (cumulative) for storage — v2 /main replaces
		// the session's transcript.jsonl on each write, so we must include all
		// prior content, not just the new portion.
		writeOpts.CompactTranscript = compactTranscriptForV2(compactCtx, ag, redacted, 0)
		writeOpts.CompactTranscriptStart = computeCompactTranscriptStart(compactCtx, ag, state, redacted.Bytes(), scopedCompact)
	}
	return time.Since(compactStart)
}

	return errCount
}

// buildFinalizeCompactTranscript generates the compact transcript for a single checkpoint
// during turn-end finalization. It reads the checkpoint's transcript start offset and
// dispatches to external compaction, in-process compaction, or skips as appropriate.
func buildFinalizeCompactTranscript(
	ctx context.Context,
	store *checkpoint.GitStore,
	v2Store *checkpoint.V2GitStore,
	v2Only bool,
	cpID id.CheckpointID,
	cpIDStr string,
	state *SessionState,
	redactedTranscript redact.RedactedBytes,
) []byte {
	finalAg, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; compactTranscriptForV2 handles nil
	var (
		content *checkpoint.SessionContent
		readErr error
	)
	if v2Only {
		content, readErr = v2Store.ReadSessionContentByID(ctx, cpID, state.SessionID)
	} else {
		content, readErr = store.ReadSessionContentByID(ctx, cpID, state.SessionID)
	}
	startLine := 0
	if readErr == nil && content != nil {
		startLine = content.Metadata.GetTranscriptStart()
	} else {
		errMsg := "unknown"
		if readErr != nil {
			errMsg = readErr.Error()
		}
		logging.Debug(ctx, "finalize: failed to read checkpoint metadata, using full transcript for compact output",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
			slog.String("error", errMsg),
		)
	}

	if compactor, ok := agent.AsTranscriptCompactor(finalAg); ok {
		if startLine == 0 {
			if compacted := compactTranscriptForExternalAgent(ctx, compactor, state.SessionID, state.TranscriptPath); compacted != nil {
				return compacted.Transcript
			}
		} else {
			logging.Warn(ctx, "external transcript compaction finalization skipped: checkpoint has non-zero compact transcript start",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("session_id", state.SessionID),
				slog.String("agent", string(compactor.Name())),
				slog.Int("compact_transcript_start", startLine),
			)
		}
		return nil
	}
	if _, ok := finalAg.(agent.CapabilityDeclarer); ok {
		logging.Warn(ctx, "external transcript compaction unavailable, skipping transcript.jsonl finalization",
			slog.String("session_id", state.SessionID),
			slog.String("agent", string(finalAg.Name())),
		)
		return nil
	}
	return compactTranscriptForV2(ctx, finalAg, redactedTranscript, startLine)
}

// filesChangedInCommit returns the set of files changed in a commit using git diff-tree.
// Uses the git CLI for faster performance vs go-git tree walks (lower constant factors).
// Falls back to go-git tree walk if git diff-tree fails, since an empty result would
// break downstream condensation and carry-forward logic.

// run executes a subcommand on the external binary and returns stdout bytes.
// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
// included in the returned error.
func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
	// Apply a default timeout when the caller hasn't set a deadline, so a hung
	// external binary can't block the CLI (or git hooks) indefinitely.
	if _, ok := ctx.Deadline(); !ok {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
		defer cancel()
	}
	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
	// Ensure I/O goroutines are released shortly after the process is killed,
	// so cmd.Run() doesn't block waiting for pipe reads.
	cmd.WaitDelay = 3 * time.Second

	// Set environment: repo root + protocol version
	cmd.Env = append(cmd.Environ(),
		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
	)
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
		cmd.Dir = repoRoot
	}

	if stdin != nil {
		cmd.Stdin = bytes.NewReader(stdin)
	}

	const maxOutputBytes = 10 * 1024 * 1024 // 10 MB

	var stdoutBuf, stderrBuf bytes.Buffer
	stdoutLW := &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
	stderrLW := &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
	cmd.Stdout = stdoutLW
	cmd.Stderr = stderrLW

	if err := cmd.Run(); err != nil {
		errMsg := strings.TrimSpace(stderrBuf.String())

